import{_ as a,o as i,c as d,a2 as l}from"./chunks/framework.CWASMpdJ.js";const f=JSON.parse('{"title":"Changelog","description":"Every Nette API release with its added, changed and fixed items.","frontmatter":{"title":"Changelog","description":"Every Nette API release with its added, changed and fixed items."},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1793038056000}'),r={name:"changelog.md"};function t(o,e,n,h,s,u){return i(),d("div",null,[...e[0]||(e[0]=[l('<h1 id="change-log" tabindex="-1">Change Log <a class="header-anchor" href="#change-log" aria-label="Permalink to &quot;Change Log&quot;">​</a></h1><p>All notable changes to this project will be documented in this file. Updates should follow the <a href="http://keepachangelog.com/" target="_blank" rel="noreferrer">Keep a CHANGELOG</a> principles.</p><h2 id="unreleased-unreleased" tabindex="-1">[Unreleased][unreleased] <a class="header-anchor" href="#unreleased-unreleased" aria-label="Permalink to &quot;[Unreleased][unreleased]&quot;">​</a></h2><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><code>BasicAuthentication</code> and <code>StaticTokenRepository</code> compare passwords and tokens with <code>hash_equals()</code> (constant time) instead of <code>===</code> / <code>in_array()</code>. Results are unchanged, including for non-string passwords and numeric tokens, which never matched before and still don&#39;t.</li></ul><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>ApiPresenter::setCorsAllowedOrigins()</code>: opt-in CORS allowlist based on the <code>Origin</code> header (with optional credentials and <code>Vary: Origin</code>). Existing <code>setCorsHeader()</code> values, including <code>&#39;auto&#39;</code>, behave exactly as before.</li><li>README: warning about the <code>&#39;auto&#39;</code> CORS mode (any site can make credentialed requests) and a migration path to the allowlist.</li><li><code>ApiPresenter::setMaskedLogHeaders()</code>: opt-in masking of sensitive request header values (<code>Authorization</code>, <code>Proxy-Authorization</code>, <code>Cookie</code>, <code>Set-Cookie</code>, <code>X-Api-Key</code> by default, or a custom case-insensitive list) before they are passed to <code>ApiLoggerInterface</code>. Logging is unchanged unless enabled.</li></ul><h2 id="_3-5-0" tabindex="-1">3.5.0 <a class="header-anchor" href="#_3-5-0" aria-label="Permalink to &quot;3.5.0&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added support for PHP 8.5</li></ul><h2 id="_3-4-5" tabindex="-1">3.4.5 <a class="header-anchor" href="#_3-4-5" aria-label="Permalink to &quot;3.4.5&quot;">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>OpenApiHandler: ErrorWrongInput can contain any message in the response.</li></ul><h2 id="_3-4-4" tabindex="-1">3.4.4 <a class="header-anchor" href="#_3-4-4" aria-label="Permalink to &quot;3.4.4&quot;">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Multi value validation and transformation if expected type is not array but instead expects array of specific type. For example if expected type is integer and value is array of integers, validation and transformation will pass.</li><li>Added check for required numeric values in InputValidator&#39;s transformType method.</li></ul><h2 id="_3-4-3" tabindex="-1">3.4.3 <a class="header-anchor" href="#_3-4-3" aria-label="Permalink to &quot;3.4.3&quot;">​</a></h2><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Invalid input type returned when value is empty in InputValidator</li></ul><h2 id="_3-4-2" tabindex="-1">3.4.2 <a class="header-anchor" href="#_3-4-2" aria-label="Permalink to &quot;3.4.2&quot;">​</a></h2><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Input validation before authorization check in ApiPresenter (causes issues with some authorization handlers that need to check input params)</li></ul><h2 id="_3-4-1" tabindex="-1">3.4.1 <a class="header-anchor" href="#_3-4-1" aria-label="Permalink to &quot;3.4.1&quot;">​</a></h2><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Don&#39;t overwrite global preflight handler if it is set and enableGlobalPreflight is called without parameter</li></ul><h2 id="_3-4-0" tabindex="-1">3.4.0 <a class="header-anchor" href="#_3-4-0" aria-label="Permalink to &quot;3.4.0&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Allowed endpoints filter for OpenApiHandler</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Support for justinrainbow/json-schema (causes issues with validating schema)</li></ul><h2 id="_3-3-0" tabindex="-1">3.3.0 <a class="header-anchor" href="#_3-3-0" aria-label="Permalink to &quot;3.3.0&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>update minimum PHP to version 8.2 (currently still supported version) + update league/fractal library [BC]</li><li>change Inject from PHPDoc format to native PHP attribute</li><li>[Reverted] Remove BC addApi register method now requires ApiHandlerInterface as second parameter instead of string or service name</li></ul><h2 id="_3-2-0" tabindex="-1">3.2.0 <a class="header-anchor" href="#_3-2-0" aria-label="Permalink to &quot;3.2.0&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Input type validation for InputParam</li></ul><ul><li>Allow justinrainbow/json-schema to use v6 if necessary</li></ul><h2 id="_3-1-0" tabindex="-1">3.1.0 <a class="header-anchor" href="#_3-1-0" aria-label="Permalink to &quot;3.1.0&quot;">​</a></h2><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Update Request body schema in OpenApiHandler</li><li>Set null value when process empty file params, instead of false</li><li>[BC] Update to php &gt;= 8.3, support for 8.4</li><li>[BC] addApi register method now requires ApiHandlerInterface as second parameter instead of string or service name</li></ul><h2 id="_3-0-0" tabindex="-1">3.0.0 <a class="header-anchor" href="#_3-0-0" aria-label="Permalink to &quot;3.0.0&quot;">​</a></h2><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Support for semantic versioning api.</li><li>[BC] DefaultHandler response code 404 instead 400</li><li>[BC] Added Container to API Decider</li><li>[BC] Output Configurator, Allows different methods for output configuration. Needs to be added to config services.</li><li>[BC] Error handler, Allows for custom error handling of handle method. Needs to be added to config services.</li><li>Query configurator rework</li></ul><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>CorsPreflightHandlerInterface - resolve multiple service registered handler error</li><li>Lazy API handlers</li></ul><h2 id="_2-12-0" tabindex="-1">2.12.0 <a class="header-anchor" href="#_2-12-0" aria-label="Permalink to &quot;2.12.0&quot;">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Button to copy <code>Body</code> content in api console</li><li>Ability to disable schema validation and provide additional error info with get parameters.</li></ul><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Handler tag wrapper has changed class from <code>btn</code> to <code>label</code></li></ul><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Allowed equal definitions in different handlers in OpenAPIHandler</li></ul><h2 id="_2-11-0" tabindex="-1">2.11.0 <a class="header-anchor" href="#_2-11-0" aria-label="Permalink to &quot;2.11.0&quot;">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Support for symfony/yaml ^5.0 and ^6.0</li><li>Support for JsonSerializable payload in JsonApiResponse</li><li>Support for latte/latte ^3.0 (Added Latte extension for ApiLink)</li></ul><h2 id="_2-10-1" tabindex="-1">2.10.1 <a class="header-anchor" href="#_2-10-1" aria-label="Permalink to &quot;2.10.1&quot;">​</a></h2><h3 id="fixed-6" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-6" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fix <em>null</em> <code>$body</code> for php 8.0</li></ul><h2 id="_2-10-0-2023-03-21" tabindex="-1">2.10.0 - 2023-03-21 <a class="header-anchor" href="#_2-10-0-2023-03-21" aria-label="Permalink to &quot;2.10.0 - 2023-03-21&quot;">​</a></h2><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Allow to set expiration to false in JsonApiResponse and XmlApiResponse</li><li>Render body of response if there is a debug message: Tracy Debug Bar</li></ul><h3 id="fixed-7" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-7" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed request url separator if url already contain some param</li></ul><h2 id="_2-9-0-2022-11-10" tabindex="-1">2.9.0 - 2022-11-10 <a class="header-anchor" href="#_2-9-0-2022-11-10" aria-label="Permalink to &quot;2.9.0 - 2022-11-10&quot;">​</a></h2><h3 id="added-8" tabindex="-1">Added <a class="header-anchor" href="#added-8" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Support for generating examples for RawInputParam by OpenApiHandler</li><li>PHP 8.1 support (<code>league/fractal</code> 0.20.1)</li><li>PHP 8.2 support</li><li>Support for <code>league/fractal</code> ~0.17 (Possible BC if you use Fractal classes, you have to update typehints)</li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>If output doesn&#39;t match any output schema, error is just logged and output is returned in production mode</li></ul><h3 id="fixed-8" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-8" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Missing expiration params in XmlApiResponse</li><li>Missing body request for PUT methost</li></ul><h2 id="_2-8-0-2022-06-15" tabindex="-1">2.8.0 - 2022-06-15 <a class="header-anchor" href="#_2-8-0-2022-06-15" aria-label="Permalink to &quot;2.8.0 - 2022-06-15&quot;">​</a></h2><h3 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>ApiLinkMacro now uses latte filter to avoid use presenter context (BC break in nette/application 3.1)</li></ul><h3 id="fixed-9" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-9" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>BaseUrl in OpenApiHandler</li></ul><h2 id="_2-7-0-2022-04-07" tabindex="-1">2.7.0 - 2022-04-07 <a class="header-anchor" href="#_2-7-0-2022-04-07" aria-label="Permalink to &quot;2.7.0 - 2022-04-07&quot;">​</a></h2><h3 id="added-9" tabindex="-1">Added <a class="header-anchor" href="#added-9" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>RedirectResponse which implements ResponseInterface</li><li>Available values now can have description in Console and OpenApiHandler. Just use associative array - keys are available values, values are their description</li></ul><h3 id="fixed-10" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-10" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Yaml format for OpenApiHandler is available only if symfony/yaml is installed</li><li>RedirectOutput use new RedirectResponse</li><li>Property with name <code>type</code> is now available in json schema</li></ul><h2 id="_2-6-0-2021-10-08" tabindex="-1">2.6.0 - 2021-10-08 <a class="header-anchor" href="#_2-6-0-2021-10-08" aria-label="Permalink to &quot;2.6.0 - 2021-10-08&quot;">​</a></h2><h3 id="updated" tabindex="-1">Updated <a class="header-anchor" href="#updated" aria-label="Permalink to &quot;Updated&quot;">​</a></h3><ul><li>Use relaxed TokenRepositoryInterface in BearerTokenAuthorization (<a href="https://github.com/tomaj/nette-api/pull/112" target="_blank" rel="noreferrer">more info here</a>)</li></ul><h2 id="_2-5-0-2021-09-17" tabindex="-1">2.5.0 - 2021-09-17 <a class="header-anchor" href="#_2-5-0-2021-09-17" aria-label="Permalink to &quot;2.5.0 - 2021-09-17&quot;">​</a></h2><h3 id="fixed-11" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-11" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Empty console input fixed by adding checkbox for each parameter</li><li>Handling wrong input for Get and Post InputParam</li><li>File and cookie parameters in Open API handler</li><li>Correct error shown when putting non-OutputInterface into ApiHandlerInterface::outputs()</li></ul><h2 id="_2-4-0-2021-04-24" tabindex="-1">2.4.0 - 2021-04-24 <a class="header-anchor" href="#_2-4-0-2021-04-24" aria-label="Permalink to &quot;2.4.0 - 2021-04-24&quot;">​</a></h2><h3 id="added-10" tabindex="-1">Added <a class="header-anchor" href="#added-10" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>User can set own form renderer for API console and own template file(s) for API console and for API listing</li></ul><h2 id="_2-3-1-2021-04-13" tabindex="-1">2.3.1 - 2021-04-13 <a class="header-anchor" href="#_2-3-1-2021-04-13" aria-label="Permalink to &quot;2.3.1 - 2021-04-13&quot;">​</a></h2><h3 id="fixed-12" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-12" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Added RateLimit to ApiDecider::addApi</li></ul><h2 id="_2-3-0-2021-01-20" tabindex="-1">2.3.0 - 2021-01-20 <a class="header-anchor" href="#_2-3-0-2021-01-20" aria-label="Permalink to &quot;2.3.0 - 2021-01-20&quot;">​</a></h2><h3 id="changed-6" tabindex="-1">Changed <a class="header-anchor" href="#changed-6" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Form in API console is rendered with BootstrapVerticalRenderer instead of BootstrapRenderer (labels are over fields instead of left side)</li></ul><h3 id="added-11" tabindex="-1">Added <a class="header-anchor" href="#added-11" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p>Added API key authentication (query, header, cookie) - see <a href="https://swagger.io/docs/specification/authentication/api-keys/" target="_blank" rel="noreferrer">https://swagger.io/docs/specification/authentication/api-keys/</a></p></li><li><p>Added missing strict_types declarations</p></li></ul><h3 id="fixed-13" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-13" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Open API handler warnings about unused security schemes</p></li><li><p>ApiPresenter detailed error unit test</p></li><li><p>Compatibility with latte 2.9.0</p></li></ul><h2 id="_2-2-0-2020-08-27" tabindex="-1">2.2.0 - 2020-08-27 <a class="header-anchor" href="#_2-2-0-2020-08-27" aria-label="Permalink to &quot;2.2.0 - 2020-08-27&quot;">​</a></h2><h3 id="added-12" tabindex="-1">Added <a class="header-anchor" href="#added-12" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added Basic authentication</li></ul><h2 id="_2-1-0-2020-05-12" tabindex="-1">2.1.0 - 2020-05-12 <a class="header-anchor" href="#_2-1-0-2020-05-12" aria-label="Permalink to &quot;2.1.0 - 2020-05-12&quot;">​</a></h2><h3 id="changed-7" tabindex="-1">Changed <a class="header-anchor" href="#changed-7" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Rewritten ApiPresenter</li></ul><h3 id="added-13" tabindex="-1">Added <a class="header-anchor" href="#added-13" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added API rate limit</li><li>Added custom headers to API console</li><li>Added field for timeout to API console</li><li>OpenAPI handler</li><li>Information about RESTful urls</li></ul><h3 id="fixed-14" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-14" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed sending empty string in multi params</li><li>UrlEncoding values sending through get param inputs</li><li>Fixed static url part <code>/api/</code> in console</li><li>Fixed generating urls in console for RESTful urls using ApiLink and EndpointInterface</li></ul><h2 id="_2-0-1-2020-03-24" tabindex="-1">2.0.1 - 2020-03-24 <a class="header-anchor" href="#_2-0-1-2020-03-24" aria-label="Permalink to &quot;2.0.1 - 2020-03-24&quot;">​</a></h2><h3 id="fixed-15" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-15" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed return types for ConsoleRequest::processParam() and ConsoleResponse::getResponseHeaders()</li></ul><h2 id="_2-0-0-2019-06-12" tabindex="-1">2.0.0 - 2019-06-12 <a class="header-anchor" href="#_2-0-0-2019-06-12" aria-label="Permalink to &quot;2.0.0 - 2019-06-12&quot;">​</a></h2><h3 id="changed-8" tabindex="-1">Changed <a class="header-anchor" href="#changed-8" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Updated nette libs to version 3.0.0 (BC break)</li><li>Added typehints (BC break)</li><li>Splitted InputParam to multiple subclasses (BC break)</li><li>Removed type TYPE_POST_JSON_KEY (BC break)</li><li>Wrong input now returns code 400 instead of 500 (BC break if somebody checks return code)</li><li>Replaced handler information array triplet (endpoint, handler, authorization) with class Api (BC break for API console usage)</li><li>Renamed some methods from ApiDecider (BC break)</li><li>Pretty JSON output in API console - without escaping unicode and slashes</li></ul><h3 id="added-14" tabindex="-1">Added <a class="header-anchor" href="#added-14" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added type JsonInputParam with scheme as replacement for type TYPE_POST_JSON_KEY</li><li>Detailed error for wrong input if debugger is enabled</li><li>Added summary (short description), description, tags and deprecated flag for API handlers</li><li>Added description, default value and example for input params</li><li>Added output validator</li></ul><h3 id="removed-1" tabindex="-1">Removed <a class="header-anchor" href="#removed-1" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Removed support for PHP 5.6, 7.0 and hhvm (BC Break)</li><li>Removed deprecated class ApiResponse (BC Break)</li></ul><h2 id="_1-17-0-2020-08-27" tabindex="-1">1.17.0 - 2020-08-27 <a class="header-anchor" href="#_1-17-0-2020-08-27" aria-label="Permalink to &quot;1.17.0 - 2020-08-27&quot;">​</a></h2><h3 id="changed-9" tabindex="-1">Changed <a class="header-anchor" href="#changed-9" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Detailed error message enabled only for non production mode</li></ul><h2 id="_1-16-0-2019-06-19" tabindex="-1">1.16.0 - 2019-06-19 <a class="header-anchor" href="#_1-16-0-2019-06-19" aria-label="Permalink to &quot;1.16.0 - 2019-06-19&quot;">​</a></h2><h3 id="added-15" tabindex="-1">Added <a class="header-anchor" href="#added-15" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added ApiLink Macro</li></ul><h2 id="_1-15-0-2019-03-13" tabindex="-1">1.15.0 - 2019-03-13 <a class="header-anchor" href="#_1-15-0-2019-03-13" aria-label="Permalink to &quot;1.15.0 - 2019-03-13&quot;">​</a></h2><h3 id="added-16" tabindex="-1">Added <a class="header-anchor" href="#added-16" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added possibility to set own scope to Manager</li><li>Added JSON validation - if JSON is invalid, throw &quot;wrong input&quot; error instead of setting params to null</li></ul><h2 id="_1-14-0-2018-08-02" tabindex="-1">1.14.0 - 2018-08-02 <a class="header-anchor" href="#_1-14-0-2018-08-02" aria-label="Permalink to &quot;1.14.0 - 2018-08-02&quot;">​</a></h2><h3 id="added-17" tabindex="-1">Added <a class="header-anchor" href="#added-17" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added possibility to set own headers for CorsPreflightHandler</li><li>Added expiration to JsonApiResponse</li></ul><h2 id="_1-13-2-2018-03-23" tabindex="-1">1.13.2 - 2018-03-23 <a class="header-anchor" href="#_1-13-2-2018-03-23" aria-label="Permalink to &quot;1.13.2 - 2018-03-23&quot;">​</a></h2><h3 id="fixed-16" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-16" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Removed names of components because of commit in nette/component-model (<a href="https://github.com/nette/component-model/commit/1fb769f4602cf82694941530bac1111b3c5cd11b" target="_blank" rel="noreferrer">https://github.com/nette/component-model/commit/1fb769f4602cf82694941530bac1111b3c5cd11b</a>)</li></ul><h2 id="_1-13-1-2018-03-16" tabindex="-1">1.13.1 - 2018-03-16 <a class="header-anchor" href="#_1-13-1-2018-03-16" aria-label="Permalink to &quot;1.13.1 - 2018-03-16&quot;">​</a></h2><h3 id="fixed-17" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-17" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed console for POST_JSON_KEY(s)</li></ul><h2 id="_1-13-0-2018-03-15" tabindex="-1">1.13.0 - 2018-03-15 <a class="header-anchor" href="#_1-13-0-2018-03-15" aria-label="Permalink to &quot;1.13.0 - 2018-03-15&quot;">​</a></h2><h3 id="added-18" tabindex="-1">Added <a class="header-anchor" href="#added-18" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>New InputParam type - POST_JSON_KEY for parsing key from json data in post body</li><li>Updated leaguge/fractal and other packages minor upgrade</li></ul><h2 id="_1-12-0-2018-02-08" tabindex="-1">1.12.0 - 2018-02-08 <a class="header-anchor" href="#_1-12-0-2018-02-08" aria-label="Permalink to &quot;1.12.0 - 2018-02-08&quot;">​</a></h2><h3 id="fixed-18" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-18" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed console POST FIELDS output for integer values</li><li>Fixed parsing headers on nginx - missing method <code>getallheaders</code></li></ul><h2 id="_1-11-0-2017-05-12" tabindex="-1">1.11.0 - 2017-05-12 <a class="header-anchor" href="#_1-11-0-2017-05-12" aria-label="Permalink to &quot;1.11.0 - 2017-05-12&quot;">​</a></h2><h3 id="added-19" tabindex="-1">Added <a class="header-anchor" href="#added-19" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added possibility to send current PHPSESSID via API Web Console</li><li>Removed Content-Type from CORS headers</li></ul><h2 id="_1-10-0-2016-12-14" tabindex="-1">1.10.0 - 2016-12-14 <a class="header-anchor" href="#_1-10-0-2016-12-14" aria-label="Permalink to &quot;1.10.0 - 2016-12-14&quot;">​</a></h2><h3 id="added-20" tabindex="-1">Added <a class="header-anchor" href="#added-20" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added X-Requested-With header to Cors handler</li></ul><h2 id="_1-9-1-2016-11-28" tabindex="-1">1.9.1 - 2016-11-28 <a class="header-anchor" href="#_1-9-1-2016-11-28" aria-label="Permalink to &quot;1.9.1 - 2016-11-28&quot;">​</a></h2><h3 id="fixed-19" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-19" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Added possibility to send empty fields via console request</li></ul><h2 id="_1-9-0-2016-11-08" tabindex="-1">1.9.0 - 2016-11-08 <a class="header-anchor" href="#_1-9-0-2016-11-08" aria-label="Permalink to &quot;1.9.0 - 2016-11-08&quot;">​</a></h2><h3 id="added-21" tabindex="-1">Added <a class="header-anchor" href="#added-21" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added support for PUT fields</li></ul><h2 id="_1-8-1-2016-10-28" tabindex="-1">1.8.1 - 2016-10-28 <a class="header-anchor" href="#_1-8-1-2016-10-28" aria-label="Permalink to &quot;1.8.1 - 2016-10-28&quot;">​</a></h2><ul><li>Updated league/fractal library to 0.14.0</li></ul><h2 id="_1-8-0-2016-09-28" tabindex="-1">1.8.0 - 2016-09-28 <a class="header-anchor" href="#_1-8-0-2016-09-28" aria-label="Permalink to &quot;1.8.0 - 2016-09-28&quot;">​</a></h2><h3 id="added-22" tabindex="-1">Added <a class="header-anchor" href="#added-22" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added cors headers - Access-Control-Allow-Headers and Access-Control-Allow-Methods</li></ul><h2 id="_1-7-0-2016-09-11" tabindex="-1">1.7.0 - 2016-09-11 <a class="header-anchor" href="#_1-7-0-2016-09-11" aria-label="Permalink to &quot;1.7.0 - 2016-09-11&quot;">​</a></h2><h3 id="added-23" tabindex="-1">Added <a class="header-anchor" href="#added-23" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added default CORS preflight handler</li><li>Added possibility to enable global preflight handler for all handlers with <code>enableGlobalPreflight()</code> on <code>ApiDecider</code></li></ul><h2 id="_1-6-2-2016-07-22" tabindex="-1">1.6.2 - 2016-07-22 <a class="header-anchor" href="#_1-6-2-2016-07-22" aria-label="Permalink to &quot;1.6.2 - 2016-07-22&quot;">​</a></h2><h3 id="fixed-20" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-20" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>InputParam validation of multi params, if available values are defined</li></ul><h2 id="_1-6-1-2016-07-05" tabindex="-1">1.6.1 - 2016-07-05 <a class="header-anchor" href="#_1-6-1-2016-07-05" aria-label="Permalink to &quot;1.6.1 - 2016-07-05&quot;">​</a></h2><h3 id="changed-10" tabindex="-1">Changed <a class="header-anchor" href="#changed-10" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>End of support for php &lt; 5.6</li><li>Service of type Tomaj\\NetteApi\\Misc\\IpDetectorInterface is no more required if service of type Tomaj\\NetteApi\\Logger\\ApiLoggerInterface is not configured and used</li><li>Service of type Tomaj\\NetteApi\\Logger\\ApiLoggerInterface need not be named &quot;apiLogger&quot;</li></ul><h2 id="_1-6-0-2016-05-11" tabindex="-1">1.6.0 - 2016-05-11 <a class="header-anchor" href="#_1-6-0-2016-05-11" aria-label="Permalink to &quot;1.6.0 - 2016-05-11&quot;">​</a></h2><h3 id="added-24" tabindex="-1">Added <a class="header-anchor" href="#added-24" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added Content-Length header to Json and Xml responses</li></ul><h2 id="_1-5-0-2016-05-04" tabindex="-1">1.5.0 - 2016-05-04 <a class="header-anchor" href="#_1-5-0-2016-05-04" aria-label="Permalink to &quot;1.5.0 - 2016-05-04&quot;">​</a></h2><h3 id="changed-11" tabindex="-1">Changed <a class="header-anchor" href="#changed-11" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>ApiPresenter: getRequestDomain() returns port as well</li><li>Updated JsonApiResponse - separate charset from content type as changed in nette/application 2.3.12</li><li>Also change nette/application minimal version to 2.3.12</li></ul><h2 id="_1-4-0-2016-04-01" tabindex="-1">1.4.0 - 2016-04-01 <a class="header-anchor" href="#_1-4-0-2016-04-01" aria-label="Permalink to &quot;1.4.0 - 2016-04-01&quot;">​</a></h2><h3 id="changed-12" tabindex="-1">Changed <a class="header-anchor" href="#changed-12" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>changed rendering in API console when available values are set</li></ul><h3 id="fxed" tabindex="-1">Fxed <a class="header-anchor" href="#fxed" aria-label="Permalink to &quot;Fxed&quot;">​</a></h3><ul><li>fixed negative values for response time in API web console</li></ul><h2 id="_1-3-0-2016-02-17" tabindex="-1">1.3.0 - 2016-02-17 <a class="header-anchor" href="#_1-3-0-2016-02-17" aria-label="Permalink to &quot;1.3.0 - 2016-02-17&quot;">​</a></h2><h3 id="added-25" tabindex="-1">Added <a class="header-anchor" href="#added-25" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>added tracy for error logging from ApiPresenter</li><li>added tests for ApiPresenter</li></ul><h2 id="_1-2-0-2016-02-11" tabindex="-1">1.2.0 - 2016-02-11 <a class="header-anchor" href="#_1-2-0-2016-02-11" aria-label="Permalink to &quot;1.2.0 - 2016-02-11&quot;">​</a></h2><h3 id="added-26" tabindex="-1">Added <a class="header-anchor" href="#added-26" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>New ability to send new input types: <ul><li>send RAW POST data</li><li>send COOKIES</li><li>send FILEs</li><li>(more info in readme section Inputs)</li></ul></li><li>all new types are available in test console for easy testing api calls</li></ul><h2 id="_1-1-0-2016-01-15" tabindex="-1">1.1.0 - 2016-01-15 <a class="header-anchor" href="#_1-1-0-2016-01-15" aria-label="Permalink to &quot;1.1.0 - 2016-01-15&quot;">​</a></h2><h3 id="added-27" tabindex="-1">Added <a class="header-anchor" href="#added-27" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added CORS support to ApiPresenter. Available options: <ul><li>&#39;auto&#39; - send back header Access-Control-Allow-Origin with domain that made request</li><li>&#39;<em>&#39; - send header with &#39;</em>&#39; - this will work fine if you dont need to send cookies via ajax calls to api with jquery $.ajax with xhrFields: { withCredentials: true } settings</li><li>&#39;off&#39; - will not send any CORS header</li><li>other - any other value will be send in Access-Control-Allow-Origin header</li></ul></li><li>Rewritten few internal functions</li></ul><h2 id="_1-0-1-2015-01-07" tabindex="-1">1.0.1 - 2015-01-07 <a class="header-anchor" href="#_1-0-1-2015-01-07" aria-label="Permalink to &quot;1.0.1 - 2015-01-07&quot;">​</a></h2><h3 id="fixed-21" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-21" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed parsing array variables from GET and POST when using multi InputParam</li></ul><h2 id="_1-0-0-2016-01-06" tabindex="-1">1.0.0 - 2016-01-06 <a class="header-anchor" href="#_1-0-0-2016-01-06" aria-label="Permalink to &quot;1.0.0 - 2016-01-06&quot;">​</a></h2><h3 id="added-28" tabindex="-1">Added <a class="header-anchor" href="#added-28" aria-label="Permalink to &quot;Added&quot;">​</a></h3><p>First version that can be used for api. Contains</p><ul><li>Authorization</li><li>Handling api request</li><li>Logging</li><li>UI Control for api listing</li><li>UI Control for web console to test api endpoints</li><li>Api versioning</li></ul><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="what-is-in-the-unreleased-section" tabindex="-1">What is in the Unreleased section? <a class="header-anchor" href="#what-is-in-the-unreleased-section" aria-label="Permalink to &quot;What is in the Unreleased section?&quot;">​</a></h3><p>Changes merged into the main branch for the upcoming 3.6.0 release. The pages mark them with a &quot;Since 3.6.0&quot; note, see <a href="/nette-api/pr-preview/pr-184/guide/versioning.html">Versions of this documentation</a>.</p><h3 id="what-does-bc-mean" tabindex="-1">What does [BC] mean? <a class="header-anchor" href="#what-does-bc-mean" aria-label="Permalink to &quot;What does [BC] mean?&quot;">​</a></h3><p>A backward incompatible change. They appear only in major releases; the <a href="/nette-api/pr-preview/pr-184/upgrade.html">upgrade guide</a> explains how to update your code.</p><h3 id="which-release-does-this-documentation-describe" tabindex="-1">Which release does this documentation describe? <a class="header-anchor" href="#which-release-does-this-documentation-describe" aria-label="Permalink to &quot;Which release does this documentation describe?&quot;">​</a></h3><p>The 3.x line, with 3.5.0 as the current release. See <a href="/nette-api/pr-preview/pr-184/guide/versioning.html">Versions of this documentation</a>.</p>',203)])])}const p=a(r,[["render",t]]);export{f as __pageData,p as default};
